async function read(){if(!db)return renderError('Supabase failed to load.');let s=await db.auth.getSession(),tq=await db.from('tournaments').select('*').order('created_at',{ascending:false}),teamq=await db.from('teams').select('*'),cq=await db.from('categories').select('*').order('name');user=s.data.session?.user||null;if(tq.error||teamq.error||cq.error)return renderError(tq.error?.message||teamq.error?.message||cq.error?.message);tournaments=tq.data||[];categories=cq.data||[];teams=teamq.data||[];let id=new URLSearchParams(location.search).get('id'),active=tournaments.find(x=>x.status==='active');tournament=id?tournaments.find(x=>x.id===id):(active||null);maps=[];scores=[];draft={};if(tournament){let mq=await db.from('maps').select('*').eq('tournament_id',tournament.id).order('map_number'),ids=(mq.data||[]).map(m=>m.id),sq=ids.length?await db.from('map_scores').select('*').in('map_id',ids):{data:[]};if(mq.error||sq.error)return renderError(mq.error?.message||sq.error?.message);maps=mq.data||[];scores=sq.data||[];let cm=current();if(cm)scores.filter(x=>x.map_id===cm.id).forEach(x=>draft[x.team_id]={kills:x.kills||0,placement_points:x.placement_points||0});}render();}
