function bind(){document.querySelector('#login')?.addEventListener('click',login);document.querySelector('#logout')?.addEventListener('click',async()=>{await db.auth.signOut();read()});document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{if(!user)return login();let d=dFor(b.dataset.id),f=b.dataset.field;d[f]=Math.max(0,(+d[f]||0)+ +b.dataset.adjust);draft[b.dataset.id]=d;syncScore(b.dataset.id);refreshScoreUI()});document.querySelectorAll('[data-value]').forEach(i=>i.onchange=()=>{if(!user)return login();let d=dFor(i.dataset.id);d[i.dataset.value]=Math.max(0,parseInt(i.value,10)||0);draft[i.dataset.id]=d;syncScore(i.dataset.id);refreshScoreUI()});document.querySelector('#discard')?.addEventListener('click',()=>{if(confirm('รีเซ็ตคะแนน Live ของแมพนี้ทั้งหมด?')){teams.forEach(t=>draft[t.id]={kills:0,placement_points:0});teams.forEach(t=>syncScore(t.id));render()}});document.querySelector('#save-map')?.addEventListener('click',saveMap);let actions=document.querySelector('.map-actions');if(actions){let end=document.createElement('button');end.id='end-tournament';end.className='danger';end.textContent='END TOURNAMENT';actions.prepend(end);end.onclick=endTournament}document.querySelector('#add-team')?.addEventListener('submit',addTeam);document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>deleteTeam(b.dataset.del));}
async function addTeam(e){e.preventDefault();if(!user)return login();let f=new FormData(e.target),name=f.get('name').trim(),shortName=name.replace(/[^a-z0-9]/gi,'').slice(0,5).toUpperCase(),q=await db.from('teams').insert({name,short_name:shortName,team_color:'ffffffff',image_file_name:shortName?`${shortName}.png`:'',logo:'',score:0,kills:0});if(q.error)return alert(q.error.message);e.target.reset();read();}
