function syncScore(teamId){let oldTimer=scoreSyncTimers.get(teamId);if(oldTimer)clearTimeout(oldTimer);setSave('UPDATING…','saving');scoreSyncTimers.set(teamId,setTimeout(()=>{scoreSyncTimers.delete(teamId);let previous=scoreSyncQueues.get(teamId)||Promise.resolve(),next=previous.catch(()=>{}).then(()=>persistScore(teamId));scoreSyncQueues.set(teamId,next);next.then(()=>{if(scoreSyncQueues.get(teamId)===next){scoreSyncQueues.delete(teamId);if(!scoreSyncTimers.size&&!scoreSyncQueues.size)setSave('LIVE SYNCED')}})},180));}
