function refreshScoreUI(){let ranked=totals(),byId=new Map(ranked.map(row=>[row.id,row]));document.querySelectorAll('.team-slot[data-team]').forEach(slot=>{let id=slot.dataset.team,d=dFor(id);slot.querySelector('[data-value="kills"]').value=d.kills;slot.querySelector('[data-value="placement_points"]').value=d.placement_points;slot.querySelector('[data-map-total]').textContent=d.kills+d.placement_points;slot.querySelector('[data-total]').textContent=byId.get(id)?.points||0});document.querySelectorAll('.entry-row[data-id]').forEach(row=>{let d=dFor(row.dataset.id);row.querySelector('.map-total').textContent=d.kills+d.placement_points;row.querySelector('.overall-total').textContent=byId.get(row.dataset.id)?.points||0});let standingsNode=document.querySelector('.live-standings-panel .standings');if(standingsNode){capture();standingsNode.outerHTML=standings(ranked,true);bindTotalEditing();motion();}}
