async function saveTeamTotal(teamId,value){if(!user)return login();let target=Math.max(0,Math.trunc(Number(value)||0)),currentTotal=totals().find(x=>x.id===teamId)?.points||0,adjustment=adjustmentFor(teamId)+target-currentTotal,previous=tournament.points_adjustments||{},next={...previous};if(adjustment)next[teamId]=adjustment;else delete next[teamId];tournament.points_adjustments=next;editingTotalId=null;setSave('UPDATING…','saving');render();let q=await db.from('tournaments').update({points_adjustments:next}).eq('id',tournament.id);if(q.error){tournament.points_adjustments=previous;render();setSave('SYNC FAILED','saving');alert(q.error.message)}else setSave('LIVE SYNCED');}
