function bindTotalEditing(){if(!document.querySelector('.live-standings-panel'))return;document.querySelectorAll('[data-edit-total]').forEach(button=>button.onclick=()=>{if(!user)return login();editingTotalId=button.dataset.editTotal;editingKillsId=null;render();let input=document.querySelector('[data-total-input]');input?.focus();input?.select()});document.querySelectorAll('[data-total-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();saveTeamTotal(form.dataset.totalForm,form.querySelector('[data-total-input]').value)});document.querySelectorAll('[data-cancel-total]').forEach(button=>button.onclick=()=>{editingTotalId=null;render()});document.querySelectorAll('[data-edit-kills]').forEach(button=>button.onclick=()=>{if(!user)return login();editingKillsId=button.dataset.editKills;editingTotalId=null;render();let input=document.querySelector('[data-kills-input]');input?.focus();input?.select()});document.querySelectorAll('[data-kills-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();saveTeamKills(form.dataset.killsForm,form.querySelector('[data-kills-input]').value)});document.querySelectorAll('[data-cancel-kills]').forEach(button=>button.onclick=()=>{editingKillsId=null;render()});}
