function overlay(){if(!tournament)return;app.innerHTML=`<section class="board match-board"><div class="overlay-title">${esc(tournament.name)} <span>${tournament.status==='complete'?'FINAL':'MAP '+tournament.current_map+'/'+tournament.total_maps}</span></div>${standings(totals().slice(0,OVERLAY_TEAM_LIMIT))}</section>`}
function library(){let cards=tournaments.map(t=>`<article class="tournament-card ${t.status==='archived'?'is-archived':''}"><div><small>${esc(t.category||'UNCATEGORIZED')}</small><h2>${esc(t.name)}</h2><p>${t.total_maps} MAPS · ${t.status.toUpperCase()} · ${new Date(t.created_at).toLocaleDateString()}</p></div><div class="card-actions"><a class="primary" href="/control?id=${t.id}">${t.status==='active'?'OPEN LIVE':'VIEW RESULTS'}</a><a href="/detail?id=${t.id}">HISTORY</a><button data-tournament-archive="${t.id}">${t.status==='archived'?'RESTORE':'ARCHIVE'}</button></div></article>`).join('')||'<p class="empty">NO TOURNAMENTS YET</p>';app.innerHTML=`<main class="shell"><header class="topbar"><div><small>TOXIC GREEN · TOURNAMENT MANAGER</small><h1>Tournaments</h1><p>สร้าง เปิด และย้อนดูรายการแข่งทั้งหมด</p></div><div class="top-actions">${user?'<button id="logout">LOG OUT</button>':'<button id="login" class="primary">ADMIN LOGIN</button>'}${nav('admin')}</div></header><section class="library-toolbar"><div class="category-list">${categories.map(c=>`<span>${esc(c.name)}</span>`).join('')||'<span>NO CATEGORIES</span>'}</div><div class="library-actions"><a href="/teams">MANAGE TEAMS</a><a class="primary" href="/create">+ CREATE TOURNAMENT</a></div></section><section class="tournament-grid">${cards}</section></main>`;document.querySelector('#login')?.addEventListener('click',login);document.querySelector('#logout')?.addEventListener('click',async()=>{await db.auth.signOut();read()});document.querySelectorAll('[data-tournament-archive]').forEach(b=>b.onclick=()=>archiveTournament(b.dataset.tournamentArchive));}
function create(){app.innerHTML=`<main class="shell setup"><header class="topbar"><div><small>TOXIC GREEN · TOURNAMENT MANAGER</small><h1>Create Tournament</h1><p>รายการใหม่จะพร้อมอัปเดต Live ทันทีหลังสร้าง</p></div>${nav('admin')}</header><section class="setup-panel"><small>EVENT DETAILS</small><h2>NEW TOURNAMENT</h2><form id="create-tournament"><input name="name" required maxlength="64" placeholder="TOURNAMENT NAME"><input name="category" list="category-options" required maxlength="32" placeholder="CATEGORY"><datalist id="category-options">${categories.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist><input name="maps" type="number" min="1" max="20" value="3"><button class="primary">CREATE & GO LIVE</button></form><p>เลือก Category เดิมหรือพิมพ์ชื่อใหม่เพื่อสร้างหมวดใหม่</p></section></main>`;document.querySelector('#create-tournament').onsubmit=createTournament;}
async function createTournament(e){e.preventDefault();if(!user)return login();let f=new FormData(e.target),name=f.get('name').trim(),category=f.get('category').trim(),total=Math.max(1,Math.min(20,+f.get('maps')||3));let cq=await db.from('categories').upsert({name:category},{onConflict:'name'});if(cq.error)return alert(cq.error.message);let q=await db.from('tournaments').insert({name,category,total_maps:total,current_map:1,status:'active'}).select().single();if(q.error)return alert(q.error.message);q=await db.from('maps').insert({tournament_id:q.data.id,map_number:1,status:'live'});if(q.error)return alert(q.error.message);location.href='/control?id='+q.data.id;}
function detail(){if(!tournament)return library();let cards=maps.map(m=>{let rows=rank(teams.map(t=>{let s=scores.find(x=>x.map_id===m.id&&x.team_id===t.id)||{};return {id:t.id,name:t.name,logo:t.logo,points:(s.kills||0)+(s.placement_points||0),kills:s.kills||0}}));return `<section class="history-map"><div><small>MAP ${m.map_number} · ${m.status.toUpperCase()}</small><h2>Map ${m.map_number}</h2></div>${standings(rows)}</section>`}).join('')||'<p class="empty">NO MAPS RECORDED</p>';app.innerHTML=`<main class="shell"><header class="topbar"><div><small>${esc(tournament.category||'UNCATEGORIZED')}</small><h1>${esc(tournament.name)}</h1><p>ประวัติผลแข่งรายแมพ</p></div><div class="top-actions"><a class="primary" href="/control?id=${tournament.id}">OPEN CONTROL</a>${nav('admin')}</div></header>${cards}</main>`;}
let allTeams=[],teamSort='name-asc';
async function read(){if(!db)return renderError('Supabase failed to load.');let s=await db.auth.getSession(),tq=await db.from('tournaments').select('*').order('created_at',{ascending:false}),teamq=await db.from('teams').select('*'),cq=await db.from('categories').select('*').order('name');user=s.data.session?.user||null;if(tq.error||teamq.error||cq.error)return renderError(tq.error?.message||teamq.error?.message||cq.error?.message);tournaments=tq.data||[];categories=cq.data||[];allTeams=teamq.data||[];let id=new URLSearchParams(location.search).get('id'),active=tournaments.find(x=>x.status==='active');tournament=id?tournaments.find(x=>x.id===id):(active||null);teams=tournament?.team_ids?.length?allTeams.filter(t=>tournament.team_ids.includes(t.id)):allTeams.filter(t=>t.active!==false);maps=[];scores=[];draft={};if(tournament){let mq=await db.from('maps').select('*').eq('tournament_id',tournament.id).order('map_number'),ids=(mq.data||[]).map(m=>m.id),sq=ids.length?await db.from('map_scores').select('*').in('map_id',ids):{data:[]};if(mq.error||sq.error)return renderError(mq.error?.message||sq.error?.message);maps=mq.data||[];scores=sq.data||[];let cm=current();if(cm)scores.filter(x=>x.map_id===cm.id).forEach(x=>draft[x.team_id]={kills:x.kills||0,placement_points:x.placement_points||0});}render();}
function create(){let available=allTeams.filter(t=>t.active!==false).sort((a,b)=>a.name.localeCompare(b.name,'th',{sensitivity:'base'})),choices=available.map(t=>`<label class="team-choice"><input type="checkbox" name="team_ids" value="${t.id}">${logo(t)}<span>${esc(t.name)}</span></label>`).join('');app.innerHTML=`<main class="shell setup"><header class="topbar"><div><small>TOXIC GREEN · TOURNAMENT MANAGER</small><h1>Create Tournament</h1><p>เลือกทีมจากคลัง ก่อนเริ่มรายการ</p></div>${nav('create')}</header><section class="setup-panel"><small>EVENT DETAILS</small><h2>NEW TOURNAMENT</h2><form id="create-tournament"><input name="name" required maxlength="64" placeholder="TOURNAMENT NAME"><input name="category" list="category-options" required maxlength="32" placeholder="CATEGORY"><datalist id="category-options">${categories.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist><input name="maps" type="number" min="1" max="20" value="3"><div class="team-picker"><b>SELECT TEAMS</b><a href="/teams">MANAGE TEAM LIBRARY</a><div>${choices||'<p class="empty">CREATE A TEAM FIRST</p>'}</div></div><button class="primary" ${available.length?'':'disabled'}>CREATE & GO LIVE</button></form></section></main>`;document.querySelector('#create-tournament').onsubmit=createTournament;}
async function createTournament(e){e.preventDefault();if(!user)return login();let f=new FormData(e.target),name=f.get('name').trim(),category=f.get('category').trim(),total=Math.max(1,Math.min(20,+f.get('maps')||3)),team_ids=f.getAll('team_ids');if(!team_ids.length)return alert('เลือกอย่างน้อย 1 ทีม');if(team_ids.length>20)return alert('เลือกได้สูงสุด 20 ทีม');let team_slots=[...team_ids,...Array(20).fill(null)].slice(0,20),observer_numbers=Object.fromEntries(team_ids.map((id,index)=>[id,index+1])),cq=await db.from('categories').upsert({name:category},{onConflict:'name'});if(cq.error)return alert(cq.error.message);let q=await db.from('tournaments').insert({name,category,team_ids,team_slots,observer_numbers,total_maps:total,current_map:1,status:'active'}).select().single();if(q.error)return alert(q.error.message);q=await db.from('maps').insert({tournament_id:q.data.id,map_number:1,status:'live'});if(q.error)return alert(q.error.message);location.href='/control?id='+q.data.id;}
function sortTeams(rows,sortBy=teamSort){return [...rows].sort((a,b)=>{if(sortBy==='date-newest'||sortBy==='date-oldest'){let difference=(Date.parse(a.created_at)||0)-(Date.parse(b.created_at)||0);return sortBy==='date-newest'?-difference:difference}return a.name.localeCompare(b.name,'th',{sensitivity:'base'})})}
function teamLibrary(){let list=sortTeams(allTeams).map(t=>`<article class="team-library-row ${t.active===false?'is-archived':''}" data-team-name="${esc(t.name)}" data-created-at="${esc(t.created_at||'')}"><div class="team">${logo(t)}<input data-team-name="${t.id}" value="${esc(t.name)}" maxlength="32"></div><div class="team-library-actions"><button data-logo="${t.id}">CHANGE LOGO</button><button data-rename="${t.id}">SAVE NAME</button><button data-team-archive="${t.id}">${t.active===false?'RESTORE':'ARCHIVE'}</button></div></article>`).join('')||'<p class="empty">NO TEAMS YET</p>';app.innerHTML=`<main class="shell"><header class="topbar"><div><small>TOXIC GREEN · SHARED TEAM LIBRARY</small><h1>Teams</h1><p>สร้าง แก้ชื่อ เปลี่ยนโลโก้ หรือ Archive ทีมโดยไม่ลบประวัติแข่ง</p></div>${nav('teams')}</header><section class="team-library-add"><form id="new-library-team"><input name="name" required maxlength="32" placeholder="NEW TEAM NAME"><button class="primary">+ ADD TEAM</button></form><div class="team-library-sort"><label for="team-sort">SORT BY</label><select id="team-sort"><option value="name-asc" ${teamSort==='name-asc'?'selected':''}>Name A-Z</option><option value="date-newest" ${teamSort==='date-newest'?'selected':''}>Date added: newest</option><option value="date-oldest" ${teamSort==='date-oldest'?'selected':''}>Date added: oldest</option></select></div></section><section class="team-library-list">${list}</section><input id="team-logo-file" hidden type="file" accept="image/png,image/jpeg"></main>`;document.querySelector('#new-library-team').onsubmit=addTeam;document.querySelector('#team-sort').onchange=e=>{teamSort=e.target.value;let container=document.querySelector('.team-library-list'),rows=[...container.querySelectorAll('.team-library-row')].map(row=>({element:row,name:row.dataset.teamName,created_at:row.dataset.createdAt}));sortTeams(rows).forEach(row=>container.append(row.element))};document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>renameTeam(b.dataset.rename));document.querySelectorAll('[data-logo]').forEach(b=>b.onclick=()=>{uploadId=b.dataset.logo;document.querySelector('#team-logo-file').click()});document.querySelectorAll('[data-team-archive]').forEach(b=>b.onclick=()=>archiveTeam(b.dataset.teamArchive));document.querySelector('#team-logo-file').onchange=e=>uploadTeamLogo(e.target.files[0],uploadId);}
function control(){if(!tournament)return library();let finished=tournament.status==='complete',ranked=totals(),rows=ranked.map((total,i)=>entry(teams.find(t=>t.id===total.id),i)).join('');app.innerHTML=`<main class="shell"><header class="topbar"><div><small>TOXIC GREEN · ${esc(tournament.name)}</small><h1>Map ${tournament.current_map} <em>/ ${tournament.total_maps}</em></h1><p>${finished?'TOURNAMENT COMPLETE · ผลการแข่งขันถูกบันทึกแล้ว':'ทุกคะแนน sync ไปยัง Live และ OBS ทันที · Rank เรียงจาก TOTAL PTS'}</p></div><div class="top-actions">${user?'<button id="logout">LOG OUT</button>':'<button id="login" class="primary">ADMIN LOGIN</button>'}${nav('admin')}</div></header><section class="command-strip"><div><span class="live-dot"></span><b>${finished?'FINAL RESULTS':'LIVE · MAP '+tournament.current_map}</b><span>${teams.length} TEAMS</span></div><span data-save-state data-state="saved">${finished?'COMPLETE':'LIVE SYNCED'}</span></section>${finished?'':`<section class="map-entry"><div class="entry-title"><small>LIVE MAP ENTRY · RANK BY TOTAL PTS</small><h2>MAP ${tournament.current_map} RESULTS</h2></div><div class="entry-head"><span>RANK</span><span>TEAM</span><span>KILLS</span><span>PLACE PTS</span><span>MAP PTS</span><span>TOTAL PTS</span></div><div class="entry-list">${rows||'<p class="empty">ADD TEAMS BEFORE RECORDING RESULTS</p>'}</div><div class="map-actions"><button id="discard">RESET LIVE MAP</button><button id="save-map" class="primary" ${teams.length?'':'disabled'}>${tournament.current_map===tournament.total_maps?'END FINAL MAP':'END MAP '+tournament.current_map+' & START MAP '+(tournament.current_map+1)}</button></div></section>`}<section class="totals"><div><small>LIVE TOURNAMENT TOTAL · SORTED BY TOTAL PTS</small><h2>TOURNAMENT STANDINGS</h2></div>${standings(ranked)}</section></main>`;bind();}
async function renameTeam(id){if(!user)return login();let input=document.querySelector(`[data-team-name="${id}"]`),name=input.value.trim();if(!name)return;let q=await db.from('teams').update({name}).eq('id',id);if(q.error)return alert(q.error.message);read();}
async function archiveTeam(id){if(!user)return login();let team=allTeams.find(t=>t.id===id),active=team?.active===false;if(!confirm(active?'กู้คืนทีมนี้?':'Archive ทีมนี้? ทีมจะไม่แสดงในรายการเลือก แต่ประวัติเดิมยังอยู่'))return;let q=await db.from('teams').update({active}).eq('id',id);if(q.error)return alert(q.error.message);read();}
async function archiveTournament(id){if(!user)return login();let item=tournaments.find(t=>t.id===id),archived=item?.status==='archived';if(!confirm(archived?'กู้คืน Tournament นี้?':'Archive Tournament นี้? ประวัติและผลคะแนนจะยังอยู่'))return;let q=await db.from('tournaments').update({status:archived?'complete':'archived'}).eq('id',id);if(q.error)return alert(q.error.message);read();}
async function uploadTeamLogo(file,id){if(!user||!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>5242880)return alert('ใช้ PNG/JPG ขนาดไม่เกิน 5 MB');let ext=file.type==='image/png'?'png':'jpg',path=`${user.id}/team-${id}-${Date.now()}.${ext}`,q=await db.storage.from(bucket).upload(path,file,{contentType:file.type});if(q.error)return alert(q.error.message);let logoUrl=db.storage.from(bucket).getPublicUrl(path).data.publicUrl,team=allTeams.find(item=>item.id===id),image_file_name=team?.image_file_name||`${(team?.short_name||team?.name||'TEAM').replace(/[^a-z0-9_-]/gi,'_')}.${ext}`;q=await db.from('teams').update({logo:logoUrl,image_file_name}).eq('id',id);if(q.error)return alert(q.error.message);read();}
function control(){if(!tournament)return library();let finished=tournament.status==='complete',ranked=totals(),lockedRows=teams.map((team,i)=>entry(team,i)).join('');app.innerHTML=`<main class="shell"><header class="topbar"><div><small>TOXIC GREEN · ${esc(tournament.name)}</small><h1>Map ${tournament.current_map} <em>/ ${tournament.total_maps}</em></h1><p>${finished?'TOURNAMENT COMPLETE · ผลการแข่งขันถูกบันทึกแล้ว':'Live Entry ลำดับทีมคงที่ · คะแนนอัปเดต Overlay ทันที'}</p></div><div class="top-actions">${user?'<button id="logout">LOG OUT</button>':'<button id="login" class="primary">ADMIN LOGIN</button>'}${nav('admin')}</div></header><section class="command-strip"><div><span class="live-dot"></span><b>${finished?'FINAL RESULTS':'LIVE · MAP '+tournament.current_map}</b><span>${teams.length} TEAMS</span></div><span data-save-state data-state="saved">${finished?'COMPLETE':'LIVE SYNCED'}</span></section>${finished?'':`<section class="map-entry locked-entry"><div class="entry-title"><small>LIVE MAP ENTRY · FIXED TEAM ORDER</small><h2>ENTER MAP ${tournament.current_map} RESULTS</h2></div><p class="entry-note">แถวทีมถูกล็อกไว้ระหว่างกรอกคะแนน เพื่อไม่ให้รายการเลื่อนตามอันดับ</p><div class="entry-head"><span>ORDER</span><span>TEAM</span><span>KILLS</span><span>PLACE PTS</span><span>MAP PTS</span><span>TOTAL PTS</span></div><div class="entry-list">${lockedRows||'<p class="empty">ADD TEAMS BEFORE RECORDING RESULTS</p>'}</div><div class="map-actions"><button id="discard">RESET LIVE MAP</button><button id="save-map" class="primary" ${teams.length?'':'disabled'}>${tournament.current_map===tournament.total_maps?'END FINAL MAP':'END MAP '+tournament.current_map+' & START MAP '+(tournament.current_map+1)}</button></div></section>`}<section class="totals"><div><small>LIVE TOURNAMENT TOTAL · RANK BY TOTAL PTS</small><h2>TOURNAMENT STANDINGS</h2></div>${standings(ranked)}</section></main>`;bind();}
function control(){if(!tournament)return library();let finished=tournament.status==='complete',ranked=totals(),lockedRows=teams.map((team,i)=>entry(team,i)).join(''),entryPanel=finished?'':`<section class="map-entry locked-entry"><div class="entry-title"><div><small>LIVE MAP ENTRY · FIXED TEAM ORDER</small><h2>ENTER MAP ${tournament.current_map} RESULTS</h2></div><span class="fixed-badge">ROWS LOCKED</span></div><p class="entry-note">รายการทีมคงที่ระหว่างกรอกคะแนน · ตารางคะแนนสดอยู่ด้านขวา</p><div class="entry-head"><span>ORDER</span><span>TEAM</span><span>KILLS</span><span>PLACE PTS</span><span>MAP PTS</span><span>TOTAL PTS</span></div><div class="entry-list">${lockedRows||'<p class="empty">ADD TEAMS BEFORE RECORDING RESULTS</p>'}</div><div class="map-actions"><button id="discard">RESET LIVE MAP</button><button id="save-map" class="primary" ${teams.length?'':'disabled'}>${tournament.current_map===tournament.total_maps?'END FINAL MAP':'END MAP '+tournament.current_map+' & START MAP '+(tournament.current_map+1)}</button></div></section>`;app.innerHTML=`<main class="shell control-shell"><header class="topbar"><div><small>TOXIC GREEN · ${esc(tournament.name)}</small><h1>Map ${tournament.current_map} <em>/ ${tournament.total_maps}</em></h1><p>${finished?'TOURNAMENT COMPLETE · ผลการแข่งขันถูกบันทึกแล้ว':'ทุกคะแนน sync ไป Live และ Overlay ทันที'}</p></div><div class="top-actions">${user?'<button id="logout">LOG OUT</button>':'<button id="login" class="primary">ADMIN LOGIN</button>'}${nav('admin')}</div></header><section class="command-strip"><div><span class="live-dot"></span><b>${finished?'FINAL RESULTS':'LIVE SCORING · MAP '+tournament.current_map}</b><span>${teams.length} TEAMS</span></div><span data-save-state data-state="saved">${finished?'COMPLETE':'LIVE SYNCED'}</span></section><section class="live-control-grid">${entryPanel}<aside class="totals live-standings-panel"><div><small>PUBLIC VIEW</small><h2>LIVE STANDINGS</h2><p class="sync-label"><span class="live-dot"></span>AUTO SYNCED TO OVERLAY</p></div>${standings(ranked)}<p class="sidebar-note">อันดับเปลี่ยนตาม TOTAL PTS<br>และ Kills ใช้ตัดสินเมื่อแต้มเท่ากัน</p></aside></section></main>`;bind();}
function slotCard(team,index){if(!team)return `<article class="team-slot is-empty" data-slot="${index}" aria-label="ช่องว่าง"><b>${String(index+1).padStart(2,'0')}</b><button class="slot-add" type="button" onclick="showSlotTeamPicker(${index})" aria-label="เพิ่มทีมในช่อง ${index+1}">+</button></article>`;let d=dFor(team.id),sum=d.kills+d.placement_points,all=totals().find(x=>x.id===team.id);return `<article class="team-slot" draggable="true" data-slot="${index}" data-team="${team.id}"><header><b>${String(index+1).padStart(2,'0')}</b><span>DRAG TO REORDER</span></header><div class="team">${logo(team)}<strong>${esc(team.name)}</strong></div><div class="slot-metrics"><label>KILLS${metric('KILLS',d.kills,team.id,'kills')}</label><label>PLACE PTS${metric('PLACE PTS',d.placement_points,team.id,'placement_points')}</label></div><footer><span>MAP PTS <b data-map-total>${sum}</b></span><span>TOTAL <b data-total>${all?.points||0}</b></span></footer></article>`}
async function saveSlots(ids){if(!user)return login();let q=await db.from('tournaments').update({team_slots:ids}).eq('id',tournament.id);if(q.error)return alert(q.error.message);tournament.team_slots=ids;teams=eventTeams();render();}
function showSlotTeamPicker(index){let slot=document.querySelector(`.team-slot[data-slot="${index}"]`),used=new Set(slots().filter(Boolean)),available=allTeams.filter(t=>t.active!==false&&!used.has(t.id)).sort((a,b)=>a.name.localeCompare(b.name,'th',{sensitivity:'base'}));if(!available.length)return alert('ไม่มีทีมว่างในคลังให้เพิ่ม');let button=slot?.querySelector('.slot-add');if(!button)return;button.outerHTML=`<select class="slot-team-select" onchange="addExistingTeamToSlot(${index},this.value)"><option value="">เลือกทีม</option>${available.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select>`;slot.querySelector('.slot-team-select')?.focus();}
async function addExistingTeamToSlot(index,id){if(!id)return;if(!user)return login();let ids=slots();if(ids[index])return alert('ช่องนี้มีทีมอยู่แล้ว');if(!allTeams.some(t=>t.id===id&&t.active!==false))return alert('ไม่พบทีมที่เลือก');ids[index]=id;let team_ids=ids.filter(Boolean),q=await db.from('tournaments').update({team_ids,team_slots:ids}).eq('id',tournament.id);if(q.error)return alert(q.error.message);read();}
function enableSlotDrag(){let source=null;document.querySelectorAll('.team-slot').forEach(slot=>{slot.ondragstart=e=>{if(slot.classList.contains('is-empty'))return e.preventDefault();source=+slot.dataset.slot;slot.classList.add('is-dragging')};slot.ondragend=()=>slot.classList.remove('is-dragging');slot.ondragover=e=>{e.preventDefault();slot.classList.add('is-over')};slot.ondragleave=()=>slot.classList.remove('is-over');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('is-over');let target=+slot.dataset.slot;if(source===null||source===target)return;let ids=slots(),moved=ids[source];ids[source]=ids[target];ids[target]=moved;saveSlots(ids);source=null}})}
