function observer(){if(!tournament)return library();observerRosterDirty=false;let selected=new Set(observerSelectedIds()),numbers=tournament.observer_numbers||{},available=allTeams.filter(team=>team.active!==false||selected.has(team.id)).sort((a,b)=>a.name.localeCompare(b.name,'th',{sensitivity:'base'})),items=available.map((team,index)=>{let checked=selected.has(team.id),defaultNumber=checked?Math.max(1,Math.trunc(Number(numbers[team.id])||observerSelectedIds().indexOf(team.id)+1)):index+1;return `<label class="observer-team ${checked?'is-selected':''}"><input type="checkbox" name="observer_team" value="${team.id}" ${checked?'checked':''}><span class="observer-team-logo">${logo(team)}</span><span class="observer-team-name"><strong>${esc(team.name)}</strong><small>${esc(team.short_name||'SHORT NAME REQUIRED')}</small></span><input class="observer-number" type="number" min="1" max="99" name="number_${team.id}" value="${defaultNumber}" ${checked?'':'disabled'} aria-label="TeamNumber for ${esc(team.name)}"></label>`}).join(''),rows=observerRows(),validCount=rows.length>0&&rows.length<=20&&rows.every(row=>row.TeamShortName)&&new Set(rows.map(row=>row.TeamNumber)).size===rows.length&&new Set(rows.map(row=>row.ImageFileName.toLowerCase())).size===rows.length,validZip=validCount&&rows.every(row=>row.team.logo),preview=rows.map(row=>`<tr><td>${row.TeamNumber}</td><td>${esc(row.TeamName)}</td><td>${esc(row.TeamShortName||'MISSING')}</td><td>${esc(row.ImageFileName)}</td><td><code>${row.TeamColor}</code></td><td>${row.team.logo?'READY':'NO LOGO'}</td></tr>`).join('');app.innerHTML=`<main class="shell observer-shell"><header class="topbar"><div><small>TOXIC GREEN · ${esc(tournament.name)}</small><h1>Observer Export</h1><p>เลือกทีมและตั้ง TeamNumber สำหรับ Tournament นี้</p></div><div class="top-actions">${nav('observer')}</div></header><section class="observer-roster"><div class="observer-section-heading"><div><small>TOURNAMENT ROSTER</small><h2>SELECT TEAMS</h2><p>ตัวเลข TeamNumber เริ่มใหม่ทุก Tournament · เลือกได้สูงสุด 20 ทีม</p></div><span id="observer-selected-count" class="${selected.size>20?'is-over-limit':''}">${selected.size} / 20</span></div><form id="observer-roster-form"><div class="observer-team-list">${items||'<p class="empty">NO TEAMS IN LIBRARY</p>'}</div><div class="observer-actions"><button class="primary" type="submit">SAVE TEAMS & NUMBERS</button><span id="observer-save-state" role="status"></span></div></form></section><section class="observer-export"><div class="observer-section-heading"><div><small>OBSERVER FILE</small><h2>CSV PREVIEW</h2><p>CSV columns follow the Observer format. ZIP contains observer.csv and all selected logo files.</p></div><div class="observer-downloads"><button id="download-observer-csv" ${validCount?'':'disabled'}>DOWNLOAD CSV</button><button id="download-observer-zip" class="primary" ${validZip?'':'disabled'}>DOWNLOAD ZIP + LOGOS</button></div></div><div class="observer-table-wrap"><table class="observer-table"><thead><tr><th>TeamNumber</th><th>TeamName</th><th>TeamShortName</th><th>ImageFileName</th><th>TeamColor</th><th>Logo</th></tr></thead><tbody>${preview||'<tr><td colspan="6">เลือกทีมแล้วกด Save เพื่อดู Preview</td></tr>'}</tbody></table></div></section></main>`;document.querySelectorAll('[name="observer_team"]').forEach(input=>input.onchange=()=>{observerRosterDirty=true;let number=input.closest('.observer-team').querySelector('.observer-number');number.disabled=!input.checked;input.closest('.observer-team').classList.toggle('is-selected',input.checked);let count=document.querySelectorAll('[name="observer_team"]:checked').length,counter=document.querySelector('#observer-selected-count');counter.textContent=`${count} / 20 · UNSAVED`;counter.classList.toggle('is-over-limit',count>20);document.querySelector('#download-observer-csv').disabled=true;document.querySelector('#download-observer-zip').disabled=true});document.querySelectorAll('.observer-number').forEach(input=>input.oninput=()=>{observerRosterDirty=true;let count=document.querySelectorAll('[name="observer_team"]:checked').length,counter=document.querySelector('#observer-selected-count');counter.textContent=`${count} / 20 · UNSAVED`;counter.classList.toggle('is-over-limit',count>20);document.querySelector('#download-observer-csv').disabled=true;document.querySelector('#download-observer-zip').disabled=true});document.querySelector('#observer-roster-form').onsubmit=saveObserverRoster;document.querySelector('#download-observer-csv').onclick=downloadObserverCsv;document.querySelector('#download-observer-zip').onclick=downloadObserverZip;}
async function saveObserverRoster(e){e.preventDefault();if(!user)return login();let selected=[...document.querySelectorAll('[name="observer_team"]:checked')],state=document.querySelector('#observer-save-state');if(!selected.length)return alert('เลือกอย่างน้อย 1 ทีม');if(selected.length>20)return alert('เลือกได้สูงสุด 20 ทีม');let ids=[],numbers={};for(let [index,input] of selected.entries()){let numberInput=input.closest('.observer-team').querySelector('.observer-number'),number=Number(numberInput.value);if(!Number.isInteger(number)||number<1||number>99)return alert('TeamNumber ต้องเป็นเลข 1 ถึง 99');if(Object.values(numbers).includes(number))return alert(`TeamNumber ${number} ซ้ำกัน`);ids.push(input.value);numbers[input.value]=number}let previousOrder=observerSelectedIds(),ordered=[...ids].sort((a,b)=>{let left=Number(numbers[a]),right=Number(numbers[b]);return left-right||previousOrder.indexOf(a)-previousOrder.indexOf(b)}),q=await db.from('tournaments').update({team_ids:ordered,team_slots:[...ordered,...Array(20-ordered.length).fill(null)],observer_numbers:numbers}).eq('id',tournament.id);if(q.error)return alert(q.error.message);state.textContent='SAVED';await read();}
function renderError(m){app.innerHTML=`<main class="shell"><section class="empty"><h2>CONNECTION ERROR</h2><p>${esc(m)}</p><button onclick="location.reload()">RETRY</button></section></main>`}
function addCopyTournamentNameButton(view){let copy=async(button,name,label)=>{try{await navigator.clipboard.writeText(name);button.textContent='COPIED ✓';setTimeout(()=>button.textContent=label,1400)}catch{alert('ไม่สามารถคัดลอกชื่อรายการได้')}};if(view==='admin'){document.querySelectorAll('[data-tournament-name]').forEach(input=>{let actions=input.closest('.tournament-card')?.querySelector('.card-actions');if(!actions)return;let button=document.createElement('button');button.type='button';button.textContent='COPY NAME';button.onclick=()=>copy(button,input.value,'COPY NAME');actions.append(button)});return}if(view!=='control'||!tournament)return;let actions=document.querySelector('.control-shell .top-actions');if(!actions||document.querySelector('#copy-tournament-name'))return;let button=document.createElement('button');button.id='copy-tournament-name';button.type='button';button.textContent='COPY TOURNAMENT NAME';button.onclick=()=>copy(button,tournament.name,'COPY TOURNAMENT NAME');actions.prepend(button)}
function render(){capture();let v=new URLSearchParams(location.search).get('view')||location.pathname.split('/').filter(Boolean).pop()||'admin';document.body.className=v==='overlay'?'overlay':'';({admin:library,create,teams:teamLibrary,control,detail,live,overlay,observer}[v]||library)();addCopyTournamentNameButton(v);bindTotalEditing();motion();}
if(db){db.channel('score-live').on('postgres_changes',{event:'*',schema:'public',table:'teams'},read).on('postgres_changes',{event:'*',schema:'public',table:'categories'},read).on('postgres_changes',{event:'*',schema:'public',table:'tournaments'},read).on('postgres_changes',{event:'*',schema:'public',table:'maps'},read).on('postgres_changes',{event:'*',schema:'public',table:'map_scores'},scheduleScoreRefresh).subscribe();read();render()}else renderError('Supabase failed to load.');
